text	userSuppliedItemDefText	cora	{"name": "text", "children": [{"name": "recordInfo", "children": [{"name": "dataDivider", "children": [{"name": "linkedRecordType", "value": "system"}, {"name": "linkedRecordId", "value": "cora"}]}, {"name": "validationType", "children": [{"name": "linkedRecordType", "value": "validationType"}, {"name": "linkedRecordId", "value": "coraText"}]}, {"name": "id", "value": "userSuppliedItemDefText"}, {"name": "type", "children": [{"name": "linkedRecordType", "value": "recordType"}, {"name": "linkedRecordId", "value": "text"}]}, {"name": "createdBy", "children": [{"name": "linkedRecordType", "value": "user"}, {"name": "linkedRecordId", "value": "141414"}]}, {"name": "tsCreated", "value": "2025-10-02T14:54:03.180752Z"}, {"name": "updated", "children": [{"name": "tsUpdated", "value": "2025-10-02T15:02:24.301606Z"}, {"name": "updatedBy", "children": [{"name": "linkedRecordType", "value": "user"}, {"name": "linkedRecordId", "value": "141414"}]}], "repeatId": "0"}]}, {"name": "textPart", "children": [{"name": "text", "value": "Id:t definieras manuellt av användaren när posten skapas och genereras inte automatiskt."}], "attributes": {"lang": "sv", "type": "default"}}, {"name": "textPart", "children": [{"name": "text", "value": "The Id is manually defined by the user when creating the record and is not automatically generated"}], "attributes": {"lang": "en", "type": "alternative"}}, {"name": "textPart", "children": [{"name": "text", "value": "IDen er manuelt definert av brukeren når du oppretter posten og genereres ikke automatisk"}], "attributes": {"lang": "no", "type": "alternative"}}]}
